const getConfigsForUplink = `-- name: getConfigsForUplink :many
Select "ConfigName" from "Tests"
Where "TestType" like "RFUplink"
`

func (q *Queries) getConfigsForUplink(ctx context.Context) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, getConfigsForUplink)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var ConfigName string
		if err := rows.Scan(&ConfigName); err != nil {
			return nil, err
		}
		items = append(items, ConfigName)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

