const getSpexTxSubCarriersDetails = `-- name: getSpexTxSubCarriersDetails :many
Select TxName, SubCarrierID, SubCarrierName, Frequency, ModIndex, AllowedModIndexDeviation, PeakFrequencyDeviation, AlwaysPresent from "SpecTxSubCarriers"
where "TxName" like ?
`

func (q *Queries) getSpexTxSubCarriersDetails(ctx context.Context, txname string) ([]SpecTxSubCarrier, error) {
	rows, err := q.db.QueryContext(ctx, getSpexTxSubCarriersDetails, txname)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SpecTxSubCarrier
	for rows.Next() {
		var i SpecTxSubCarrier
		if err := rows.Scan(
			&i.TxName,
			&i.SubCarrierID,
			&i.SubCarrierName,
			&i.Frequency,
			&i.ModIndex,
			&i.AllowedModIndexDeviation,
			&i.PeakFrequencyDeviation,
			&i.AlwaysPresent,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

