const getTxHarmonics = `-- name: getTxHarmonics :many
Select TxName, HarmonicsID, HarmonicType, HarmonicsName, Frequency, TotalLossFromTxToSA from "SpecTxHarmonics"
where "TxName" like ?
`

func (q *Queries) getTxHarmonics(ctx context.Context, txname string) ([]SpecTxHarmonic, error) {
	rows, err := q.db.QueryContext(ctx, getTxHarmonics, txname)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SpecTxHarmonic
	for rows.Next() {
		var i SpecTxHarmonic
		if err := rows.Scan(
			&i.TxName,
			&i.HarmonicsID,
			&i.HarmonicType,
			&i.HarmonicsName,
			&i.Frequency,
			&i.TotalLossFromTxToSA,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

